#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct attivita {
    int id;
    int priorita;
    char nome[24];
    struct attivita *prox;
} attivita_t;

typedef struct lista_att {
    attivita_t *testa;
    size_t len;
} lista_att_t;

void lista_init(lista_att_t *l) {
    l->testa = nullptr;
    l->len = 0;
}

const attivita_t *lista_cerca(const lista_att_t *l, int id) {
    for (const attivita_t *curr = l->testa; curr != nullptr; curr = curr->prox) {
        if (curr->id == id) { return curr; }
    }
    return nullptr;
}

int lista_inserisci(lista_att_t *l, int id, int priorita, const char *nome) {
    if (lista_cerca(l, id) != nullptr) { return 0; }
    attivita_t *nuovo = malloc(sizeof(*nuovo));
    if (nuovo == nullptr) { return -1; }
    nuovo->id = id;
    nuovo->priorita = priorita;
    snprintf(nuovo->nome, sizeof(nuovo->nome), "%s", nome);
    nuovo->prox = nullptr;
    attivita_t **cur = &l->testa;
    while (*cur != nullptr && ((*cur)->priorita > priorita ||
           ((*cur)->priorita == priorita && (*cur)->id < id))) {
        cur = &(*cur)->prox;
    }
    nuovo->prox = *cur;
    *cur = nuovo;
    ++l->len;
    return 1;
}

bool lista_rimuovi(lista_att_t *l, int id) {
    attivita_t **cur = &l->testa;
    while (*cur != nullptr && (*cur)->id != id) {
        cur = &(*cur)->prox;
    }
    if (*cur == nullptr) { return false; }
    attivita_t *da_lib = *cur;
    *cur = da_lib->prox;
    free(da_lib);
    --l->len;
    return true;
}

void lista_distruggi(lista_att_t *l) {
    attivita_t *curr = l->testa;
    while (curr != nullptr) {
        attivita_t *prossimo = curr->prox;
        free(curr);
        curr = prossimo;
    }
    l->testa = nullptr;
    l->len = 0;
}

int main(void) {
    lista_att_t lista;
    lista_init(&lista);
    char riga[256], cmd[16], nome[24], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        int id = 0, prio = 0;
        if (strcmp(cmd, "ADD") == 0 && sscanf(riga, "ADD %d %d %23s %c", &id, &prio, nome, &extra) == 3) {
            int esito = lista_inserisci(&lista, id, prio, nome);
            if (esito == -1) {
                lista_distruggi(&lista);
                fprintf(stderr, "Errore: memoria esaurita.\n");
                return EXIT_FAILURE;
            }
            if (esito == 0) { printf("DUPLICATO %d\n", id); }
        } else if (strcmp(cmd, "DEL") == 0 && sscanf(riga, "DEL %d %c", &id, &extra) == 1) {
            if (lista_rimuovi(&lista, id)) { printf("RIMOSSO %d\n", id); }
            else { printf("NON TROVATO %d\n", id); }
        } else if (strcmp(cmd, "FIND") == 0 && sscanf(riga, "FIND %d %c", &id, &extra) == 1) {
            const attivita_t *a = lista_cerca(&lista, id);
            if (a != nullptr) { printf("TROVATO %d: %s (prio=%d)\n", a->id, a->nome, a->priorita); }
            else { printf("NON TROVATO %d\n", id); }
        } else if (strcmp(cmd, "LIST") == 0 && sscanf(riga, "LIST %c", &extra) != 1) {
            printf("Lista (%zu):", lista.len);
            if (lista.len == 0) {
                printf(" (vuota)\n");
            } else {
                for (const attivita_t *c = lista.testa; c != nullptr; c = c->prox) {
                    printf("%s[%d] %s (p=%d)", (c == lista.testa) ? " " : " -> ", c->id, c->nome, c->priorita);
                }
                printf("\n");
            }
        } else {
            lista_distruggi(&lista);
            fprintf(stderr, "Errore: comando non valido.\n");
            return EXIT_FAILURE;
        }
    }
    lista_distruggi(&lista);
    printf("Pulizia completata (len=%zu, testa_nulla=%d)\n", lista.len, lista.testa == nullptr);
    return EXIT_SUCCESS;
}

#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct nodo_lru {
    int chiave;
    int valore;
    struct nodo_lru *prec;
    struct nodo_lru *prox;
} nodo_lru_t;

typedef struct cache_lru {
    nodo_lru_t *testa;
    nodo_lru_t *coda;
    size_t len;
    size_t cap;
} cache_lru_t;

void scollega_nodo(cache_lru_t *c, nodo_lru_t *n) {
    if (n->prec != nullptr) { n->prec->prox = n->prox; }
    else { c->testa = n->prox; }
    if (n->prox != nullptr) { n->prox->prec = n->prec; }
    else { c->coda = n->prec; }
    n->prec = nullptr;
    n->prox = nullptr;
    --c->len;
}

void collega_in_testa(cache_lru_t *c, nodo_lru_t *n) {
    n->prec = nullptr;
    n->prox = c->testa;
    if (c->testa != nullptr) { c->testa->prec = n; }
    else { c->coda = n; }
    c->testa = n;
    ++c->len;
}

void sposta_in_testa(cache_lru_t *c, nodo_lru_t *n) {
    if (c->testa == n) { return; }
    scollega_nodo(c, n);
    collega_in_testa(c, n);
}

nodo_lru_t *cerca_nodo(cache_lru_t *c, int chiave) {
    for (nodo_lru_t *curr = c->testa; curr != nullptr; curr = curr->prox) {
        if (curr->chiave == chiave) { return curr; }
    }
    return nullptr;
}

void cache_distruggi(cache_lru_t *c) {
    nodo_lru_t *curr = c->testa;
    while (curr != nullptr) {
        nodo_lru_t *prossimo = curr->prox;
        free(curr);
        curr = prossimo;
    }
    c->testa = nullptr;
    c->coda = nullptr;
    c->len = 0;
}

void cache_stampa(const cache_lru_t *c) {
    printf("AVANTI (%zu):", c->len);
    if (c->len == 0) { printf(" (vuota)\n"); }
    else {
        for (const nodo_lru_t *n = c->testa; n != nullptr; n = n->prox) {
            printf(" %d=%d", n->chiave, n->valore);
        }
        printf("\n");
    }
    printf("INDIETRO (%zu):", c->len);
    if (c->len == 0) { printf(" (vuota)\n"); }
    else {
        for (const nodo_lru_t *n = c->coda; n != nullptr; n = n->prec) {
            printf(" %d=%d", n->chiave, n->valore);
        }
        printf("\n");
    }
}

int main(void) {
    char riga[256], cmd[16], extra = '\0';
    int cap_in = 0;
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %c", &cap_in, &extra) != 1 || cap_in < 1 || cap_in > 32) {
        fprintf(stderr, "Errore: capacità cache non valida.\n");
        return EXIT_FAILURE;
    }
    cache_lru_t cache = {.testa = nullptr, .coda = nullptr, .len = 0, .cap = (size_t)cap_in};
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        int k = 0, v = 0;
        if (strcmp(cmd, "PUT") == 0 && sscanf(riga, "PUT %d %d %c", &k, &v, &extra) == 2) {
            nodo_lru_t *esistente = cerca_nodo(&cache, k);
            if (esistente != nullptr) {
                esistente->valore = v;
                sposta_in_testa(&cache, esistente);
                printf("UPDATE %d=%d\n", k, v);
            } else {
                if (cache.len == cache.cap) {
                    nodo_lru_t *vecchio = cache.coda;
                    int k_ev = vecchio->chiave;
                    scollega_nodo(&cache, vecchio);
                    free(vecchio);
                    printf("EVICT %d\n", k_ev);
                }
                nodo_lru_t *nuovo = malloc(sizeof(*nuovo));
                if (nuovo == nullptr) {
                    cache_distruggi(&cache);
                    fprintf(stderr, "Errore: memoria esaurita.\n");
                    return EXIT_FAILURE;
                }
                *nuovo = (nodo_lru_t){.chiave = k, .valore = v, .prec = nullptr, .prox = nullptr};
                collega_in_testa(&cache, nuovo);
                printf("INSERT %d=%d\n", k, v);
            }
        } else if (strcmp(cmd, "GET") == 0 && sscanf(riga, "GET %d %c", &k, &extra) == 1) {
            nodo_lru_t *n = cerca_nodo(&cache, k);
            if (n == nullptr) { printf("MISS %d\n", k); }
            else {
                sposta_in_testa(&cache, n);
                printf("HIT %d=%d\n", n->chiave, n->valore);
            }
        } else if (strcmp(cmd, "DEL") == 0 && sscanf(riga, "DEL %d %c", &k, &extra) == 1) {
            nodo_lru_t *n = cerca_nodo(&cache, k);
            if (n == nullptr) { printf("NON TROVATO %d\n", k); }
            else {
                scollega_nodo(&cache, n);
                free(n);
                printf("DEL %d\n", k);
            }
        } else if (strcmp(cmd, "DUMP") == 0 && sscanf(riga, "DUMP %c", &extra) != 1) {
            cache_stampa(&cache);
        } else {
            cache_distruggi(&cache);
            fprintf(stderr, "Errore: comando non valido.\n");
            return EXIT_FAILURE;
        }
    }
    cache_distruggi(&cache);
    return EXIT_SUCCESS;
}

#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct coda {
    int *dati;
    size_t inizio;
    size_t len;
    size_t cap;
} coda_t;

typedef struct nodo_pila {
    int id;
    struct nodo_pila *prox;
} nodo_pila_t;

typedef struct pila {
    nodo_pila_t *cima;
    size_t len;
} pila_t;

void coda_init(coda_t *c) { *c = (coda_t){}; }
void coda_distruggi(coda_t *c) { free(c->dati); *c = (coda_t){}; }

bool coda_espandi(coda_t *c) {
    size_t nuova_cap = (c->cap == 0) ? 2 : (c->cap * 2);
    if (nuova_cap < c->cap || nuova_cap > SIZE_MAX / sizeof(int)) { return false; }
    int *nuovo = malloc(nuova_cap * sizeof(int));
    if (nuovo == nullptr) { return false; }
    for (size_t i = 0; i < c->len; ++i) {
        nuovo[i] = c->dati[(c->inizio + i) % c->cap];
    }
    free(c->dati);
    c->dati = nuovo;
    c->inizio = 0;
    c->cap = nuova_cap;
    return true;
}

bool coda_enqueue(coda_t *c, int id) {
    if (c->len == c->cap && !coda_espandi(c)) { return false; }
    c->dati[(c->inizio + c->len) % c->cap] = id;
    ++c->len;
    return true;
}

bool coda_dequeue(coda_t *c, int *out) {
    if (c->len == 0) { return false; }
    *out = c->dati[c->inizio];
    c->inizio = (c->inizio + 1) % c->cap;
    --c->len;
    return true;
}

bool coda_peek(const coda_t *c, int *out) {
    if (c->len == 0) { return false; }
    *out = c->dati[c->inizio];
    return true;
}

void pila_init(pila_t *p) { *p = (pila_t){}; }

void pila_distruggi(pila_t *p) {
    nodo_pila_t *curr = p->cima;
    while (curr != nullptr) {
        nodo_pila_t *prossimo = curr->prox;
        free(curr);
        curr = prossimo;
    }
    *p = (pila_t){}; }

bool pila_push(pila_t *p, int id) {
    nodo_pila_t *n = malloc(sizeof(*n));
    if (n == nullptr) { return false; }
    n->id = id;
    n->prox = p->cima;
    p->cima = n;
    ++p->len;
    return true;
}

bool pila_pop(pila_t *p, int *out) {
    if (p->cima == nullptr) { return false; }
    nodo_pila_t *n = p->cima;
    *out = n->id;
    p->cima = n->prox;
    free(n);
    --p->len;
    return true;
}

bool pila_peek(const pila_t *p, int *out) {
    if (p->cima == nullptr) { return false; }
    *out = p->cima->id;
    return true;
}

int main(void) {
    coda_t coda;
    pila_t pila;
    coda_init(&coda);
    pila_init(&pila);
    char riga[256], cmd[16], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        int id = 0;
        if (strcmp(cmd, "ENQ") == 0 && sscanf(riga, "ENQ %d %c", &id, &extra) == 1) {
            if (!coda_enqueue(&coda, id)) {
                coda_distruggi(&coda); pila_distruggi(&pila);
                return EXIT_FAILURE;
            }
            printf("ENQ %d (coda len=%zu cap=%zu)\n", id, coda.len, coda.cap);
        } else if (strcmp(cmd, "SERVE") == 0 && sscanf(riga, "SERVE %c", &extra) != 1) {
            if (!coda_peek(&coda, &id)) {
                printf("CODA VUOTA\n");
            } else {
                if (!pila_push(&pila, id)) {
                    coda_distruggi(&coda); pila_distruggi(&pila);
                    return EXIT_FAILURE;
                }
                coda_dequeue(&coda, &id);
                printf("SERVE %d\n", id);
            }
        } else if (strcmp(cmd, "UNDO") == 0 && sscanf(riga, "UNDO %c", &extra) != 1) {
            if (!pila_peek(&pila, &id)) {
                printf("PILA VUOTA\n");
            } else {
                if (!coda_enqueue(&coda, id)) {
                    coda_distruggi(&coda); pila_distruggi(&pila);
                    return EXIT_FAILURE;
                }
                pila_pop(&pila, &id);
                printf("UNDO %d\n", id);
            }
        } else if (strcmp(cmd, "PEEK") == 0 && sscanf(riga, "PEEK %c", &extra) != 1) {
            int vc = 0, vp = 0;
            printf("PEEK coda=");
            if (coda_peek(&coda, &vc)) { printf("%d", vc); } else { printf("vuota"); }
            printf(" pila=");
            if (pila_peek(&pila, &vp)) { printf("%d\n", vp); } else { printf("vuota\n"); }
        } else if (strcmp(cmd, "STAT") == 0 && sscanf(riga, "STAT %c", &extra) != 1) {
            printf("Coda (len=%zu, cap=%zu):", coda.len, coda.cap);
            if (coda.len == 0) { printf(" (vuota)\n"); }
            else {
                for (size_t i = 0; i < coda.len; ++i) { printf(" %d", coda.dati[(coda.inizio + i) % coda.cap]); }
                printf("\n");
            }
            printf("Pila (len=%zu):", pila.len);
            if (pila.len == 0) { printf(" (vuota)\n"); }
            else {
                for (const nodo_pila_t *n = pila.cima; n != nullptr; n = n->prox) { printf(" %d", n->id); }
                printf("\n");
            }
        } else {
            coda_distruggi(&coda); pila_distruggi(&pila);
            fprintf(stderr, "Errore: comando non valido.\n");
            return EXIT_FAILURE;
        }
    }
    coda_distruggi(&coda);
    pila_distruggi(&pila);
    return EXIT_SUCCESS;
}

#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct nodo_bst {
    int32_t chiave;
    char etichetta[24];
    struct nodo_bst *sx;
    struct nodo_bst *dx;
} nodo_bst_t;

bool bst_inserisci(nodo_bst_t **rad, int32_t chiave, const char *et, bool *inserito) {
    nodo_bst_t **cur = rad;
    while (*cur != nullptr) {
        if (chiave < (*cur)->chiave) { cur = &(*cur)->sx; }
        else if (chiave > (*cur)->chiave) { cur = &(*cur)->dx; }
        else {
            snprintf((*cur)->etichetta, sizeof((*cur)->etichetta), "%s", et);
            *inserito = false;
            return true;
        }
    }
    nodo_bst_t *n = malloc(sizeof(*n));
    if (n == nullptr) { return false; }
    n->chiave = chiave;
    snprintf(n->etichetta, sizeof(n->etichetta), "%s", et);
    n->sx = nullptr;
    n->dx = nullptr;
    *cur = n;
    *inserito = true;
    return true;
}

const nodo_bst_t *bst_cerca(const nodo_bst_t *rad, int32_t chiave) {
    const nodo_bst_t *cur = rad;
    while (cur != nullptr) {
        if (chiave < cur->chiave) { cur = cur->sx; }
        else if (chiave > cur->chiave) { cur = cur->dx; }
        else { return cur; }
    }
    return nullptr;
}

nodo_bst_t *bst_rimuovi(nodo_bst_t *rad, int32_t chiave, bool *rimosso) {
    if (rad == nullptr) { return nullptr; }
    if (chiave < rad->chiave) {
        rad->sx = bst_rimuovi(rad->sx, chiave, rimosso);
        return rad;
    }
    if (chiave > rad->chiave) {
        rad->dx = bst_rimuovi(rad->dx, chiave, rimosso);
        return rad;
    }
    *rimosso = true;
    if (rad->sx == nullptr) {
        nodo_bst_t *dx = rad->dx;
        free(rad);
        return dx;
    }
    if (rad->dx == nullptr) {
        nodo_bst_t *sx = rad->sx;
        free(rad);
        return sx;
    }
    nodo_bst_t *succ = rad->dx;
    while (succ->sx != nullptr) { succ = succ->sx; }
    rad->chiave = succ->chiave;
    snprintf(rad->etichetta, sizeof(rad->etichetta), "%s", succ->etichetta);
    bool dummy = false;
    rad->dx = bst_rimuovi(rad->dx, succ->chiave, &dummy);
    return rad;
}

void bst_range(const nodo_bst_t *rad, int32_t lo, int32_t hi, size_t *trovati) {
    if (rad == nullptr) { return; }
    if (rad->chiave > lo) { bst_range(rad->sx, lo, hi, trovati); }
    if (rad->chiave >= lo && rad->chiave <= hi) {
        printf(" %" PRId32 "=%s", rad->chiave, rad->etichetta);
        ++(*trovati);
    }
    if (rad->chiave < hi) { bst_range(rad->dx, lo, hi, trovati); }
}

size_t bst_conta(const nodo_bst_t *rad) {
    return (rad == nullptr) ? 0 : (1 + bst_conta(rad->sx) + bst_conta(rad->dx));
}

size_t bst_altezza(const nodo_bst_t *rad) {
    if (rad == nullptr) { return 0; }
    size_t hs = bst_altezza(rad->sx), hd = bst_altezza(rad->dx);
    return 1 + ((hs > hd) ? hs : hd);
}

void bst_stampa_inorder(const nodo_bst_t *rad, bool *primo) {
    if (rad == nullptr) { return; }
    bst_stampa_inorder(rad->sx, primo);
    printf("%s%" PRId32, (*primo) ? "" : " ", rad->chiave);
    *primo = false;
    bst_stampa_inorder(rad->dx, primo);
}

void bst_distruggi(nodo_bst_t *rad) {
    if (rad == nullptr) { return; }
    bst_distruggi(rad->sx);
    bst_distruggi(rad->dx);
    free(rad);
}

int main(void) {
    nodo_bst_t *radice = nullptr;
    char riga[256], cmd[16], et[24], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        long long k = 0, lo = 0, hi = 0;
        if (strcmp(cmd, "PUT") == 0 && sscanf(riga, "PUT %lld %23s %c", &k, et, &extra) == 2 &&
            k >= INT32_MIN && k <= INT32_MAX) {
            bool inserito = false;
            if (!bst_inserisci(&radice, (int32_t)k, et, &inserito)) {
                bst_distruggi(radice);
                return EXIT_FAILURE;
            }
            printf("%s %" PRId32 "\n", inserito ? "INSERT" : "UPDATE", (int32_t)k);
        } else if (strcmp(cmd, "GET") == 0 && sscanf(riga, "GET %lld %c", &k, &extra) == 1 &&
                   k >= INT32_MIN && k <= INT32_MAX) {
            const nodo_bst_t *n = bst_cerca(radice, (int32_t)k);
            if (n != nullptr) { printf("GET %" PRId32 ": %s\n", (int32_t)k, n->etichetta); }
            else { printf("GET %" PRId32 ": NON TROVATO\n", (int32_t)k); }
        } else if (strcmp(cmd, "DEL") == 0 && sscanf(riga, "DEL %lld %c", &k, &extra) == 1 &&
                   k >= INT32_MIN && k <= INT32_MAX) {
            bool rimosso = false;
            radice = bst_rimuovi(radice, (int32_t)k, &rimosso);
            printf("DEL %" PRId32 ": %s\n", (int32_t)k, rimosso ? "OK" : "NON TROVATO");
        } else if (strcmp(cmd, "RANGE") == 0 && sscanf(riga, "RANGE %lld %lld %c", &lo, &hi, &extra) == 2 &&
                   lo >= INT32_MIN && hi <= INT32_MAX && lo <= hi) {
            size_t trovati = 0;
            printf("RANGE [%" PRId32 ",%" PRId32 "]:", (int32_t)lo, (int32_t)hi);
            bst_range(radice, (int32_t)lo, (int32_t)hi, &trovati);
            if (trovati == 0) { printf(" (nessuno)"); }
            printf("\n");
        } else if (strcmp(cmd, "INFO") == 0 && sscanf(riga, "INFO %c", &extra) != 1) {
            printf("INFO: nodi=%zu altezza=%zu inorder=", bst_conta(radice), bst_altezza(radice));
            if (radice == nullptr) { printf("(vuoto)\n"); }
            else {
                bool primo = true;
                bst_stampa_inorder(radice, &primo);
                printf("\n");
            }
        } else {
            bst_distruggi(radice);
            fprintf(stderr, "Errore: comando non valido.\n");
            return EXIT_FAILURE;
        }
    }
    bst_distruggi(radice);
    return EXIT_SUCCESS;
}

#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef void (*distruggi_fn)(void *dato);
typedef bool (*pred_dato_fn)(const void *dato, const void *ctx);

typedef struct nodo_gen {
    void *dato;
    struct nodo_gen *prox;
} nodo_gen_t;

typedef struct lista_gen {
    nodo_gen_t *testa;
    nodo_gen_t *coda;
    size_t len;
    distruggi_fn distruggi;
} lista_gen_t;

typedef struct documento {
    char *titolo;
    int *voti;
    size_t num_voti;
    size_t *cont_distrutti;
} documento_t;

void lg_init(lista_gen_t *l, distruggi_fn distruggi) {
    *l = (lista_gen_t){.testa = nullptr, .coda = nullptr, .len = 0, .distruggi = distruggi};
}

bool lg_inserisci_coda(lista_gen_t *l, void *dato) {
    nodo_gen_t *n = malloc(sizeof(*n));
    if (n == nullptr) { return false; }
    n->dato = dato;
    n->prox = nullptr;
    if (l->coda != nullptr) { l->coda->prox = n; }
    else { l->testa = n; }
    l->coda = n;
    ++l->len;
    return true;
}

size_t lg_rimuovi_se(lista_gen_t *l, pred_dato_fn pred, const void *ctx) {
    size_t rimossi = 0;
    nodo_gen_t *prev = nullptr;
    nodo_gen_t *curr = l->testa;
    while (curr != nullptr) {
        nodo_gen_t *prossimo = curr->prox;
        if (pred(curr->dato, ctx)) {
            if (prev != nullptr) { prev->prox = prossimo; }
            else { l->testa = prossimo; }
            if (curr == l->coda) { l->coda = prev; }
            if (l->distruggi != nullptr) { l->distruggi(curr->dato); }
            free(curr);
            --l->len;
            ++rimossi;
        } else {
            prev = curr;
        }
        curr = prossimo;
    }
    return rimossi;
}

void lg_distruggi(lista_gen_t *l) {
    nodo_gen_t *curr = l->testa;
    while (curr != nullptr) {
        nodo_gen_t *prossimo = curr->prox;
        if (l->distruggi != nullptr) { l->distruggi(curr->dato); }
        free(curr);
        curr = prossimo;
    }
    l->testa = nullptr;
    l->coda = nullptr;
    l->len = 0;
}

double media_documento(const documento_t *d) {
    if (d->num_voti == 0) { return 0.0; }
    long long s = 0;
    for (size_t i = 0; i < d->num_voti; ++i) { s += d->voti[i]; }
    return (double)s / (double)d->num_voti;
}

void distruggi_documento(void *p) {
    documento_t *d = p;
    if (d == nullptr) { return; }
    if (d->cont_distrutti != nullptr) { ++(*d->cont_distrutti); }
    free(d->titolo);
    free(d->voti);
    free(d);
}

documento_t *crea_documento(const char *titolo, const int *voti, size_t k, size_t *cont_distrutti) {
    documento_t *d = malloc(sizeof(*d));
    if (d == nullptr) { return nullptr; }
    d->titolo = strdup(titolo);
    d->voti = calloc(k, sizeof(int));
    if (d->titolo == nullptr || d->voti == nullptr) {
        free(d->titolo); free(d->voti); free(d);
        return nullptr;
    }
    for (size_t i = 0; i < k; ++i) { d->voti[i] = voti[i]; }
    d->num_voti = k;
    d->cont_distrutti = cont_distrutti;
    return d;
}

bool pred_media_sotto(const void *dato, const void *ctx) {
    const documento_t *d = dato;
    const double *soglia = ctx;
    return media_documento(d) < *soglia;
}

void stampa_lista_doc(const lista_gen_t *l) {
    if (l->len == 0) { printf(" (vuota)\n"); return; }
    for (const nodo_gen_t *n = l->testa; n != nullptr; n = n->prox) {
        const documento_t *d = n->dato;
        printf(" %s(%.2f)", d->titolo, media_documento(d));
    }
    printf("\n");
}

int main(void) {
    char riga[256], titolo[32], extra = '\0';
    int n_in = 0;
    double soglia_vista = 0.0, soglia_elim = 0.0;
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %lf %lf %c", &n_in, &soglia_vista, &soglia_elim, &extra) != 3 ||
        n_in < 0 || n_in > 16) {
        fprintf(stderr, "Errore: intestazione non valida.\n");
        return EXIT_FAILURE;
    }
    size_t n = (size_t)n_in, distrutti = 0;
    lista_gen_t lista_prop, lista_vista;
    lg_init(&lista_prop, distruggi_documento);
    lg_init(&lista_vista, nullptr);
    for (size_t i = 0; i < n; ++i) {
        int k_in = 0, letti = 0, voti[8] = {};
        if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
            sscanf(riga, "%31s %d%n", titolo, &k_in, &letti) != 2 || k_in < 1 || k_in > 8) {
            lg_distruggi(&lista_vista); lg_distruggi(&lista_prop); return EXIT_FAILURE;
        }
        const char *p = riga + letti;
        for (int j = 0; j < k_in; ++j) {
            int step = 0;
            if (sscanf(p, "%d%n", &voti[j], &step) != 1) {
                lg_distruggi(&lista_vista); lg_distruggi(&lista_prop); return EXIT_FAILURE;
            }
            p += step;
        }
        documento_t *doc = crea_documento(titolo, voti, (size_t)k_in, &distrutti);
        if (doc == nullptr || !lg_inserisci_coda(&lista_prop, doc)) {
            distruggi_documento(doc);
            lg_distruggi(&lista_vista); lg_distruggi(&lista_prop); return EXIT_FAILURE;
        }
    }
    for (const nodo_gen_t *c = lista_prop.testa; c != nullptr; c = c->prox) {
        documento_t *d = c->dato;
        if (media_documento(d) >= soglia_vista && !lg_inserisci_coda(&lista_vista, d)) {
            lg_distruggi(&lista_vista); lg_distruggi(&lista_prop); return EXIT_FAILURE;
        }
    }
    printf("Vista prestito (>= %.2f, len=%zu):", soglia_vista, lista_vista.len);
    stampa_lista_doc(&lista_vista);
    lg_distruggi(&lista_vista);
    printf("Dopo distruzione vista: distrutti=%zu\n", distrutti);
    size_t rim = lg_rimuovi_se(&lista_prop, pred_media_sotto, &soglia_elim);
    printf("Rimossi (< %.2f): %zu (distrutti=%zu)\n", soglia_elim, rim, distrutti);
    printf("Proprietaria residua (len=%zu):", lista_prop.len);
    stampa_lista_doc(&lista_prop);
    lg_distruggi(&lista_prop);
    printf("Fine programma: creati=%zu distrutti=%zu\n", n, distrutti);
    return EXIT_SUCCESS;
}
